import socket, threading, subprocess, tempfile, os, time, random, string, signal, sys
BIN='/workspace/artifacts/target/busybox'
random.seed(12345)

def run_resp(resp, timeout=1.5):
    srv=socket.socket(); srv.setsockopt(socket.SOL_SOCKET,socket.SO_REUSEADDR,1); srv.bind(('127.0.0.1',0)); srv.listen(1); port=srv.getsockname()[1]
    def th():
        try:
            srv.settimeout(timeout); c,a=srv.accept(); c.settimeout(timeout)
            try: c.recv(4096); c.sendall(resp)
            except Exception: pass
            try: c.shutdown(socket.SHUT_WR)
            except Exception: pass
            c.close()
        except Exception: pass
        finally:
            try: srv.close()
            except Exception: pass
    t=threading.Thread(target=th); t.daemon=True; t.start()
    with tempfile.TemporaryDirectory() as td:
        out=os.path.join(td,'out')
        cmd=[BIN,'wget','-O',out,f'http://127.0.0.1:{port}/x']
        try:
            p=subprocess.run(cmd,stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=timeout)
            rc=p.returncode; timed=False
        except subprocess.TimeoutExpired as e:
            return None, True, e.stdout or b'', e.stderr or b''
    t.join(0.1)
    return rc, False, p.stdout, p.stderr

def hit(rc,timed,so,se):
    s=(so or b'')+(se or b'')
    low=s.lower()
    return (not timed) and rc is not None and (rc<0 or rc>128 or b'segmentation' in low or b'aborted' in low or b'malloc' in low or b'corrupt' in low or b'free' in low or b'stack smashing' in low)

interesting=[]
# grammar-ish cases
atoms=[b'', b'0', b'1', b'-1', b'+1', b'00', b'000000000000000000000000000000000', b'999999999999999999999999999999999999999', b'0x10', b'1;ext', b'\x00', b'\r', b'\n', b'\r\n', b'A'*4095, b'A'*4096, b'A'*5000]
headers=[b'Content-Length', b'content-length', b'CONTENT-LENGTH', b'Transfer-Encoding', b'transfer-encoding', b'Location', b'location', b'Content Length', b'Content-Length ', b' Transfer-Encoding', b'X']
vals=atoms+[b'chunked', b'Chunked', b'chunked\x00x', b'gzip, chunked', b'http://127.0.0.1:1/', b'/', b'http://'+b'A'*1000+b'/', b'http://127.0.0.1:'+b'9'*1000+b'/']
idx=0
for status in [b'HTTP/1.1 200 OK', b'HTTP/1.1 204 No Content', b'HTTP/1.1 206 Partial', b'HTTP/1.1 301 Moved', b'HTTP/1.1 302 Found', b'HTTP/1.1 999 Weird', b'HTTP/1.1 -1 Weird', b'HTTP/1.1 000 Weird', b'HTTP/1.1 200', b'200 OK', b'HTTP/1.1\x00 200 OK']:
  for h in headers:
    for v in vals:
      resp=status+b'\r\n'+h+b': '+v+b'\r\n\r\nBODY'
      rc,t,so,se=run_resp(resp)
      idx+=1
      if hit(rc,t,so,se):
        print('HIT grammar', idx, status[:30], h, repr(v[:80]), 'rc', rc)
        print((se or b'')[:1000].decode('latin1','replace'))
        sys.exit(0)
print('grammar done', idx)
# random cases
chars=bytes(range(0,128))
for i in range(5000):
    n=random.randint(0,6)
    lines=[]
    if random.random()<0.8:
        code=random.choice([b'200',b'204',b'206',b'300',b'301',b'302',b'303',b'307',b'308',b'999',b'000',b'-1',bytes(str(random.randrange(1000)).encode())])
        lines.append(random.choice([b'HTTP/1.1 ', b'HTTP/1.0 ', b'', b'HTTP/9.9 '])+code+b' '+os.urandom(random.randint(0,20)).replace(b'\r',b'X').replace(b'\n',b'Y'))
    else:
        lines.append(os.urandom(random.randint(0,200)).replace(b'\r',b'X').replace(b'\n',b'Y'))
    for j in range(n):
        if random.random()<0.6:
            h=random.choice(headers)
        else:
            h=os.urandom(random.randint(0,80)).replace(b'\r',b'R').replace(b'\n',b'N')
        if random.random()<0.85:
            v=random.choice(vals)
        else:
            v=os.urandom(random.randint(0,3000)).replace(b'\r',b'R').replace(b'\n',b'N')
        sep=random.choice([b': ', b':', b' : ', b'\t:', b''])
        lines.append(h+sep+v)
    resp=b'\r\n'.join(lines)+b'\r\n\r\n'+os.urandom(random.randint(0,200))
    rc,t,so,se=run_resp(resp)
